final class _JsonCodableUnkeyedDecoder
    with _JsonPrimitiveDecoderMixin
    implements UnkeyedDecoder {
  @override
  final JsonTokenReader _reader;
  final JsonCodableDecoder _rootDecoder;
  bool _started = false;

  _JsonCodableUnkeyedDecoder(this._reader, this._rootDecoder);

  @override
  void _ensureStarted() {
    if (!_started) {
      _reader.beginArray();
      _started = true;
    }
  }

  @override
  bool moveNext() {
    _ensureStarted();
    final has = _reader.moveNext();
    if (!has) {
      _reader.endArray();
    }
    return has;
  }

  @override
  void skipElement() {
    _ensureStarted();
    _reader.skipValue();
  }

  @override
  Decoder nestedDecoder() => _rootDecoder;

  @override
  T decodeElement<T>(Decodable<T> decodable) => decodable.decode(_rootDecoder);

  @override
  T? decodeNullableElement<T>(Decodable<T> decodable) {
    if (isNextNull()) {
      readNull();
      return null;
    }
    return decodeElement(decodable);
  }

  @override
  List<int> decodeIntList() {
    _ensureStarted();
    final list = <int>[];
    _reader.beginArray();
    while (_reader.moveNext()) {
      list.add(_reader.readInt());
    }
    _reader.endArray();
    return list;
  }

  @override
  List<double> decodeDoubleList() {
    _ensureStarted();
    final list = <double>[];
    _reader.beginArray();
    while (_reader.moveNext()) {
      list.add(_reader.readDouble());
    }
    _reader.endArray();
    return list;
  }

  @override
  Float64List decodeFloat64List() {
    _ensureStarted();
    final list = <double>[];
    _reader.beginArray();
    while (_reader.moveNext()) {
      list.add(_reader.readDouble());
    }
    _reader.endArray();
    return Float64List.fromList(list);
  }

  @override
  List<String> decodeStringList() {
    _ensureStarted();
    final list = <String>[];
    _reader.beginArray();
    while (_reader.moveNext()) {
      list.add(_reader.readString());
    }
    _reader.endArray();
    return list;
  }

  @override
  List<bool> decodeBoolList() {
    _ensureStarted();
    final list = <bool>[];
    _reader.beginArray();
    while (_reader.moveNext()) {
      list.add(_reader.readBool());
    }
    _reader.endArray();
    return list;
  }
}

