/// Concrete high-performance streaming JSON encoder connecting
/// `package:codable` contracts directly to `JsonTokenWriter`.
final class JsonCodableEncoder implements Encoder {
  final JsonTokenWriter _writer;

  @override
  final Map<Object, Object?> userInfo;

  _JsonCodableKeyedEncoder? _activeKeyed;
  _JsonCodableUnkeyedEncoder? _activeUnkeyed;

  JsonCodableEncoder(this._writer, {this.userInfo = const {}});

  /// Encodes [value] to a newly allocated UTF-8 byte buffer using [encodable].
  static Uint8List toBytes<T>(
    T value,
    Encodable<T> encodable, {
    Map<Object, Object?> userInfo = const {},
    int? capacityHint,
  }) {
    final writer = AdaptiveJsonTokenWriter(capacityHint ?? 1024);
    final encoder = JsonCodableEncoder(writer, userInfo: userInfo);
    encodable.encode(value, encoder);
    encoder._finish();
    return writer.takeBytes();
  }

  /// Encodes [value] to a JSON String using [encodable].
  static String encode<T>(
    T value,
    Encodable<T> encodable, {
    Map<Object, Object?> userInfo = const {},
  }) {
    final bytes = toBytes(value, encodable, userInfo: userInfo);
    return utf8.decode(bytes);
  }

  /// Encodes [value] directly into [sink] using a chunked [JsonTokenWriter].
  static void toSink<T>(
    BytesBuilder sink,
    T value,
    Encodable<T> encodable, {
    Map<Object, Object?> userInfo = const {},
  }) {
    final writer = AdaptiveJsonTokenWriter.toSink(sink);
    final encoder = JsonCodableEncoder(writer, userInfo: userInfo);
    encodable.encode(value, encoder);
    encoder._finish();
    writer.flush();
  }

  /// Starts a chunked conversion that streams encoded UTF-8 byte chunks
  /// directly to [sink] via [JsonTokenWriter.toSink].
  static ChunkedConversionSink<T> startChunkedConversion<T>(
    Sink<List<int>> sink,
    Encodable<T> encodable, {
    Map<Object, Object?> userInfo = const {},
  }) {
    final byteSink = sink is ByteConversionSink
        ? sink
        : ByteConversionSink.from(sink);
    return _JsonCodableChunkedEncoderSink<T>(byteSink, encodable, userInfo);
  }

  void _finish() {
    _activeKeyed?._close();
    _activeKeyed = null;
    _activeUnkeyed?._close();
    _activeUnkeyed = null;
  }

  @override
  KeyedEncoder keyed({KeyOptions? options}) {
    _activeKeyed = _JsonCodableKeyedEncoder(this, _writer);
    return _activeKeyed!;
  }

  @override
  UnkeyedEncoder unkeyed() {
    _activeUnkeyed = _JsonCodableUnkeyedEncoder(this, _writer);
    return _activeUnkeyed!;
  }

  @override
  SingleValueEncoder singleValue() =>
      _JsonCodableSingleValueEncoder(this, _writer);
}

final class _JsonCodableKeyedEncoder implements KeyedEncoder {
  final JsonCodableEncoder _rootEncoder;
  final JsonTokenWriter _writer;
  bool _closed = false;

  _JsonCodableKeyedEncoder(this._rootEncoder, this._writer) {
    _writer.beginObject();
  }

  void _close() {
    if (!_closed) {
      _writer.endObject();
      _closed = true;
    }
  }

  @override
  void encodeInt(String key, int value) {
    _writer.writeName(key);
    _writer.writeInt(value);
  }

  @override
  void encodeNullableInt(String key, int? value) {
    if (value != null) {
      encodeInt(key, value);
    }
  }

  @override
  void encodeDouble(String key, double value) {
    _writer.writeName(key);
    _writer.writeDouble(value);
  }

  @override
  void encodeNullableDouble(String key, double? value) {
    if (value != null) {
      encodeDouble(key, value);
    }
  }

  @override
  void encodeString(String key, String value) {
    _writer.writeName(key);
    _writer.writeString(value);
  }

  @override
  void encodeNullableString(String key, String? value) {
    if (value != null) {
      encodeString(key, value);
    }
  }

  @override
  void encodeBool(String key, bool value) {
    _writer.writeName(key);
    _writer.writeBool(value);
  }

  @override
  void encodeNullableBool(String key, bool? value) {
    if (value != null) {
      encodeBool(key, value);
    }
  }

  @override
  void encodeNull(String key) {
    _writer.writeName(key);
    _writer.writeNull();
  }

  @override
  void encodeValue<T>(String key, T value, Encodable<T> encodable) {
    _writer.writeName(key);
    final child = JsonCodableEncoder(_writer, userInfo: _rootEncoder.userInfo);
    encodable.encode(value, child);
    child._finish();
  }

  @override
  void encodeNullableValue<T>(String key, T? value, Encodable<T> encodable) {
    if (value != null) {
      encodeValue(key, value, encodable);
    }
  }

  @override
  void encodeList<T>(String key, Iterable<T> elements, Encodable<T> encodable) {
    _writer.writeName(key);
    _writer.beginArray();
    for (final e in elements) {
      final child = JsonCodableEncoder(
        _writer,
        userInfo: _rootEncoder.userInfo,
      );
      encodable.encode(e, child);
      child._finish();
    }
    _writer.endArray();
  }

  @override
  void encodeIntList(String key, List<int> values) {
    _writer.writeName(key);
    _writer.beginArray();
    for (final v in values) {
      _writer.writeInt(v);
    }
    _writer.endArray();
  }

  @override
  void encodeDoubleList(String key, List<double> values) {
    _writer.writeName(key);
    _writer.beginArray();
    for (final v in values) {
      _writer.writeDouble(v);
    }
    _writer.endArray();
  }

  @override
  void encodeStringList(String key, List<String> values) {
    _writer.writeName(key);
    _writer.beginArray();
    for (final v in values) {
      _writer.writeString(v);
    }
    _writer.endArray();
  }

  @override
  void encodeBoolList(String key, List<bool> values) {
    _writer.writeName(key);
    _writer.beginArray();
    for (final v in values) {
      _writer.writeBool(v);
    }
    _writer.endArray();
  }
}

